import { jwtVerify } from "jose";
import { NextRequest, NextResponse } from "next/server";

const AUTH_COOKIE_NAME = "bjs_auth";

async function verifyMiddlewareSession(token: string) {
  const secretValue = process.env.JWT_SECRET;

  if (!secretValue) {
    return null;
  }

  try {
    const secret = new TextEncoder().encode(secretValue);
    const { payload } = await jwtVerify(token, secret, {
      algorithms: ["HS256"],
    });

    if (
      typeof payload.userId !== "string" ||
      (payload.role !== "student" && payload.role !== "admin") ||
      (payload.isAdmin !== undefined &&
        payload.isAdmin !== 0 &&
        payload.isAdmin !== 1)
    ) {
      return null;
    }

    return payload;
  } catch {
    return null;
  }
}

export async function middleware(req: NextRequest) {
  const pathname = req.nextUrl.pathname;
  const requestHeaders = new Headers(req.headers);
  requestHeaders.set("x-pathname", pathname);
  const response = NextResponse.next({
    request: {
      headers: requestHeaders,
    },
  });

  if (pathname.startsWith("/register")) {
    return response;
  }

  const token = req.cookies.get(AUTH_COOKIE_NAME)?.value;
  const loginUrl = new URL("/login", req.url);

  loginUrl.searchParams.set("next", pathname);

  if (!token) {
    return NextResponse.redirect(loginUrl);
  }

  const session = await verifyMiddlewareSession(token);

  if (!session) {
    return NextResponse.redirect(loginUrl);
  }

  if (
    pathname.startsWith("/admin") &&
    session.isAdmin !== 1 &&
    session.role !== "admin"
  ) {
    return NextResponse.redirect(new URL("/dashboard", req.url));
  }

  return response;
}

export const config = {
  matcher: ["/register", "/dashboard/:path*", "/admin/:path*"],
};
